"""Independent Python reference model of PROTOCOL.md v3.0 (dev only)."""
import hashlib, copy

MAXP = 2**62 - 1
MAXST = 2**60

def u(b):
    return int.from_bytes(b, 'big')

class Fail(Exception):
    def __init__(self, code): self.code = code

class CloseFail(Exception):
    def __init__(self, code, off): self.code, self.off = code, off

def sha(b):
    return hashlib.sha256(b).hexdigest()

def vdec(buf, pos):
    """overlong-allowed varint; returns (value,newpos) or raises Fail"""
    if pos[0] >= len(buf): raise Fail('FRAME_ENCODING_ERROR')
    b = buf[pos[0]]
    ln = 1 << (b >> 6)
    if pos[0] + ln > len(buf): raise Fail('FRAME_ENCODING_ERROR')
    v = b & 0x3f
    for i in range(1, ln):
        v = (v << 8) | buf[pos[0]+i]
    pos[0] += ln
    return v

def vdec_type(buf, pos):
    if pos[0] >= len(buf): raise Fail('FRAME_ENCODING_ERROR')
    b = buf[pos[0]]
    ln = 1 << (b >> 6)
    if pos[0] + ln > len(buf): raise Fail('FRAME_ENCODING_ERROR')
    v = b & 0x3f
    for i in range(1, ln):
        v = (v << 8) | buf[pos[0]+i]
    pos[0] += ln
    if ln == 2 and v < 64: raise Fail('FRAME_ENCODING_ERROR')
    if ln == 4 and v < 16384: raise Fail('FRAME_ENCODING_ERROR')
    if ln == 8 and v < 2**30: raise Fail('FRAME_ENCODING_ERROR')
    return v

def venc(v):
    if v < 64: return bytes([v])
    if v < 16384: return bytes([0x40 | (v >> 8), v & 0xff])
    if v < 2**30: return bytes([0x80 | (v >> 24), (v >> 16) & 0xff, (v >> 8) & 0xff, v & 0xff])
    return bytes([0xc0 | (v >> 56)] + [ (v >> (8*i)) & 0xff for i in range(6,-1,-1)])

def take(buf, pos, n):
    if n < 0 or n > len(buf) - pos[0]: raise Fail('FRAME_ENCODING_ERROR')
    out = bytes(buf[pos[0]:pos[0]+n]); pos[0] += n
    return out

def decode_pn(raw, width, expected):
    W = 1 << (8*width)
    d = expected - raw
    if d <= 0: return raw
    k, r = divmod(d, W)
    if 2*r >= W: k += 1
    return raw + k*W

def canon_width(pn, expected):
    for w in (1,2,3,4):
        if decode_pn(pn & (2**(8*w)-1), w, expected) == pn: return w
    return 4

def ranges_of(bytemap):
    """bytemap: dict offset->byte ; return (list of merged [s,e), unique, prefix, sha256)"""
    if not bytemap: return [], 0, 0, sha(b'')
    offs = sorted(bytemap)
    runs = []
    for o in offs:
        if runs and runs[-1][1] == o: runs[-1][1] = o+1
        else: runs.append([o, o+1])
    unique = sum(e-s for s,e in runs)
    prefix = 0
    h = hashlib.sha256()
    if runs[0][0] == 0:
        prefix = runs[0][1] - runs[0][0]
        h.update(bytes(bytemap[i] for i in range(runs[0][0], runs[0][1])))
    return [tuple(r) for r in runs], unique, prefix, h.hexdigest()

def iv_merge(ivs):
    """ivs: list of [s,e) -> merged sorted list"""
    out = []
    for s, e in sorted(ivs):
        if e <= s: continue
        if out and out[-1][1] >= s:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out

class Ref:
    def __init__(self, t):
        lim = t['limits']; loc = t['local']; pe = t['peer']
        self.limConn = lim['connection']; self.limStream = lim['stream']
        self.limBidi = lim['bidi']; self.limUni = lim['uni']; self.limCids = lim['cids']
        self.localBidi = loc['bidi']; self.localUni = loc['uni']
        self.localCids = [bytes.fromhex(c) for c in loc['cids']]
        self.peerCid = bytes.fromhex(pe['cid']); self.peerToken = bytes.fromhex(pe['token'])
        self.closed = False
        self.closeInfo = None
        self.keys = {'I'}
        self.largest = {'I': None, 'H': None, 'A': None}
        self.seen = {'I': set(), 'H': set(), 'A': set()}
        self.ack = {'I': [], 'H': [], 'A': []}   # merged ivs
        self.ecn = {'I': [0,0,0], 'H': [0,0,0], 'A': [0,0,0]}
        self.crypto = {'I': {}, 'H': {}, 'A': {}}
        self.streams = {}
        self.used = 0
        self.openBidi = 0; self.openUni = 0
        self.sendMaxData = 0
        self.smsBidi = 0; self.smsUni = 0
        self.epochs = {}   # g -> [min,max,count]
        self.currentEpoch = 0
        self.peerObs = {0: (self.peerCid, self.peerToken)}
        self.peerOwner = {self.peerCid: 0}
        self.peerActive = {0}
        self.threshold = 0
        self.retiredLocal = set()
        r = t['received']
        for lv in ('I','H','A'):
            if r[lv] is not None:
                self.largest[lv] = r[lv]; self.seen[lv].add(r[lv])
        if r['A'] is not None:
            self.epochs[0] = [r['A'], r['A'], 1]
        self.outPackets = []
        self.outDatagrams = []

    # ---------- envelope framing ----------
    def parse_header(self, w, off):
        b0 = w[off]
        p = off + 1
        res = {'off': off}
        if b0 & 0x80:
            if (b0 & 0xfc) == 0xc0: res['level'] = 'I'
            elif (b0 & 0xfc) == 0xe0: res['level'] = 'H'
            else: return None
            res['pnw'] = (b0 & 3) + 1
            if p + 4 > len(w): return None
            if w[p:p+4] != b'\x00\x00\x00\x01': return None
            p += 4
            if p >= len(w): return None
            dl = w[p]; p += 1
            if dl > 20 or p + dl > len(w): return None
            res['dcid'] = bytes(w[p:p+dl]); p += dl
            if p >= len(w): return None
            sl = w[p]; p += 1
            if sl > 20 or p + sl > len(w): return None
            res['scid'] = bytes(w[p:p+sl]); p += sl
            if res['level'] == 'I':
                try:
                    tl, p2 = vdec(w, [p])[0], None
                except Fail:
                    return None
                pos = [p]; tl = vdec(w, pos); p = pos[0]
                if tl < 0 or tl > len(w) - p: return None
                res['token'] = bytes(w[p:p+tl]); p += tl
            else:
                res['token'] = b''
            pos = [p]; 
            try:
                ln = vdec(w, pos)
            except Fail:
                return None
            p = pos[0]
            if ln < res['pnw'] or ln > len(w) - p: return None
            res['raw'] = u(w[p:p+res['pnw']])
            p += res['pnw']
            res['payload'] = bytes(w[p:p+ln-res['pnw']])
            res['next'] = p + (ln - res['pnw'])
            return res
        else:
            if (b0 & 0x40) == 0: return None
            if b0 & 0x18: return None
            res['level'] = 'A'
            res['phase'] = (b0 >> 2) & 1
            res['pnw'] = (b0 & 3) + 1
            cw = len(self.localCids[0])
            if p + cw + res['pnw'] > len(w): return None
            res['dcid'] = bytes(w[p:p+cw]); p += cw
            res['raw'] = u(w[p:p+res['pnw']])
            p += res['pnw']
            res['scid'] = b''; res['token'] = b''
            res['payload'] = bytes(w[p:])
            res['next'] = len(w)
            return res

    # ---------- run ----------
    def run(self, events):
        for ev, e in enumerate(events):
            if 'keys' in e:
                if not self.closed:
                    self.keys = set(e['keys'])
            else:
                self.do_datagram(ev, e['datagram']['wire'], e['datagram']['auth'])

    def do_datagram(self, ev, wirehex, auth):
        w = bytes.fromhex(wirehex)
        off = 0; pkt = 0
        accepted = b''
        acount = 0
        while off < len(w):
            env = self.parse_header(w, off)
            if env is None:
                self.outPackets.append(dict(event=ev, packet=pkt, offset=off, level=None,
                                            pn=None, epoch=None, status='BAD_HEADER', sha256=None))
                pkt += 1
                break
            ann = auth[pkt] if pkt < len(auth) else None
            st, h = self.do_envelope(ev, pkt, env, ann, auth)
            self.outPackets.append(dict(event=ev, packet=pkt, offset=env['off'],
                                        level=env['level'], pn=env['pn'], epoch=st[1],
                                        status=st[0], sha256=h))
            if h is not None:
                acount += 1; accepted += st[2]
            pkt += 1
            off = env['next']
        self.outDatagrams.append(dict(event=ev, packets=pkt, accepted=acount,
                                      bytes=len(accepted), sha256=sha(accepted)))

    def do_envelope(self, ev, pkt, env, ann, auth):
        lv = env['level']
        expected = self.largest[lv] + 1 if self.largest[lv] is not None else 0
        pn = decode_pn(env['raw'], env['pnw'], expected)
        env['pn'] = pn
        hashv = None; wire = None
        epoch_out = None
        if self.closed:
            status = 'CLOSED'
        elif not self.route_ok(env):
            status = 'DROP_CID'
        elif lv not in self.keys:
            status = 'NO_KEY'
        elif pn > MAXP:
            status = 'PN_RANGE'
        else:
            if lv == 'A':
                g = ann
                ok = ann is not None and ann in (self.currentEpoch-1, self.currentEpoch, self.currentEpoch+1) \
                     and (ann & 1) == env['phase']
            else:
                ok = bool(auth) and auth[0] is not None
            if not ok:
                status = 'AUTH'
            else:
                if lv == 'A': epoch_out = ann
                if pn in self.seen[lv]:
                    status = 'DUPLICATE'
                elif lv == 'A' and self.epoch_violation(ann, pn):
                    status = 'KEY_UPDATE_ERROR'
                    self.do_close(ev, pkt, 0, 'KEY_UPDATE_ERROR')
                else:
                    snap = copy.deepcopy(self.__dict__)
                    try:
                        if lv == 'A': self.apply_epoch(ann, pn)
                        status, wire = self.frame_audit(ev, pkt, env, lv, pn, expected)
                        hashv = sha(wire) if wire else None
                    except CloseFail as cf:
                        self.__dict__.clear(); self.__dict__.update(snap)
                        status = cf.code
                        self.do_close(ev, pkt, cf.off, cf.code)
        return (status, epoch_out, wire), hashv

    def route_ok(self, env):
        for i, c in enumerate(self.localCids):
            if c == env['dcid']:
                env['destSeq'] = i
                return i not in self.retiredLocal
        return False

    def do_close(self, ev, pkt, off, code):
        if not self.closed:
            self.closed = True
            self.closeInfo = dict(event=ev, packet=pkt, offset=off, code=code)

    def epoch_violation(self, g, pn):
        for h, (mn, mx, c) in self.epochs.items():
            if h < g and pn <= mx: return True
            if h > g and pn >= mn: return True
        return False

    def apply_epoch(self, g, pn):
        if g not in self.epochs:
            self.epochs[g] = [pn, pn, 1]
        else:
            mn, mx, c = self.epochs[g]
            self.epochs[g] = [min(mn, pn), max(mx, pn), c+1]
        if g == self.currentEpoch + 1:
            self.currentEpoch = g

    # ---------- frames ----------
    def frame_audit(self, ev, pkt, env, lv, pn, expected):
        pl = env['payload']
        pos = [0]
        canon = []
        try:
            if not pl: raise CloseFail('FRAME_ENCODING_ERROR', 0)
            while pos[0] < len(pl):
                fs = pos[0]
                try:
                    is_close = self.frame(pl, pos, lv, env['destSeq'], canon)
                except Fail as f:
                    raise CloseFail(f.code, fs)
                if is_close:
                    # commit + accept
                    self.accept(lv, pn)
                    wire = self.canon_env(env, pn, expected, b''.join(canon))
                    self.do_close(ev, pkt, fs, 'PEER_CLOSE')
                    return 'PEER_CLOSE', wire
            self.accept(lv, pn)
            wire = self.canon_env(env, pn, expected, b''.join(canon))
            return 'OK', wire
        except CloseFail:
            raise

    def accept(self, lv, pn):
        self.seen[lv].add(pn)
        if self.largest[lv] is None or pn > self.largest[lv]:
            self.largest[lv] = pn

    def canon_env(self, env, pn, expected, payload):
        w = canon_width(pn, expected)
        pnbytes = pn.to_bytes(w, 'big')
        out = b''
        if env['level'] == 'A':
            out += bytes([0x40 | (env['phase'] << 2) | (w-1)]) + env['dcid']
        else:
            out += bytes([(0xc0 if env['level']=='I' else 0xe0) | (w-1)]) + b'\x00\x00\x00\x01'
            out += bytes([len(env['dcid'])]) + env['dcid']
            out += bytes([len(env['scid'])]) + env['scid']
            if env['level'] == 'I':
                out += venc(len(env['token'])) + env['token']
            out += venc(w + len(payload))
        return out + pnbytes + payload

    def ref_stream(self, idv, send):
        cat = idv & 3; idx = idv >> 2
        if cat == 0:
            if idx >= self.limBidi: raise Fail('STREAM_LIMIT_ERROR')
            self.openBidi = max(self.openBidi, idx+1)
        elif cat == 2:
            if send: raise Fail('STREAM_STATE_ERROR')
            if idx >= self.limUni: raise Fail('STREAM_LIMIT_ERROR')
            self.openUni = max(self.openUni, idx+1)
        elif cat == 1:
            if idx >= self.localBidi: raise Fail('STREAM_STATE_ERROR')
        else:
            if send:
                if idx >= self.localUni: raise Fail('STREAM_STATE_ERROR')
            else:
                raise Fail('STREAM_STATE_ERROR')
        if idv not in self.streams:
            self.streams[idv] = dict(high=0, fin=None, reset=None, stop=None, send_max=0, data={})
        return self.streams[idv]

    def insert_bytes(self, store, off, data, check):
        if not data: return
        end = off + len(data)
        for i, b in enumerate(data):
            o = off + i
            if o in store:
                if check and store[o] != b: raise Fail('PROTOCOL_VIOLATION')
            else:
                store[o] = b

    def frame(self, pl, pos, lv, destSeq, canon):
        t = vdec_type(pl, pos)
        if t > 0x31: raise Fail('FRAME_ENCODING_ERROR')
        FE = 'FRAME_ENCODING_ERROR'
        def need_a():
            if lv != 'A': raise Fail('PROTOCOL_VIOLATION')
        if t == 0x00:
            canon.append(b'\x00'); return False
        if t == 0x01:
            canon.append(b'\x01'); return False
        if t in (2, 3):
            la = vdec(pl, pos); delay = vdec(pl, pos); count = vdec(pl, pos); first = vdec(pl, pos)
            if first > la: raise Fail(FE)
            rngs = [[la-first, la+1]]
            pairs = []
            low = la - first
            for _ in range(count):
                gap = vdec(pl, pos); rg = vdec(pl, pos)
                pairs.append((gap, rg))
                if low < gap + 2: raise Fail(FE)
                high = low - gap - 2
                if rg > high: raise Fail(FE)
                rngs.append([high-rg, high+1])
                low = high - rg
            e = [0,0,0]
            if t == 3:
                e = [vdec(pl, pos), vdec(pl, pos), vdec(pl, pos)]
            self.ack[lv] = iv_merge(self.ack[lv] + rngs)
            self.ecn[lv] = [max(a,b) for a,b in zip(self.ecn[lv], e)]
            out = venc(t) + venc(la) + venc(delay) + venc(count) + venc(first)
            for g, r in pairs: out += venc(g) + venc(r)
            if t == 3: out += b''.join(venc(x) for x in e)
            canon.append(out)
            return False
        if t == 0x04:
            need_a()
            idv = vdec(pl, pos); err = vdec(pl, pos); fin = vdec(pl, pos)
            s = self.ref_stream(idv, False)
            if fin < s['high']: raise Fail('FINAL_SIZE_ERROR')
            if s['fin'] is not None and s['fin'] != fin: raise Fail('FINAL_SIZE_ERROR')
            cand = max(s['high'], fin)
            if cand > self.limStream: raise Fail('FLOW_CONTROL_ERROR')
            if self.used - s['high'] + cand > self.limConn: raise Fail('FLOW_CONTROL_ERROR')
            if s['fin'] is None: s['fin'] = fin
            if s['reset'] is None: s['reset'] = err
            self.used += cand - s['high']
            s['high'] = cand
            canon.append(venc(0x04) + venc(idv) + venc(err) + venc(fin))
            return False
        if t == 0x05:
            need_a()
            idv = vdec(pl, pos); err = vdec(pl, pos)
            s = self.ref_stream(idv, True)
            if s['stop'] is None: s['stop'] = err
            canon.append(venc(0x05) + venc(idv) + venc(err))
            return False
        if t == 0x06:
            off = vdec(pl, pos); ln = vdec(pl, pos)
            if off + ln > MAXP: raise Fail(FE)
            data = take(pl, pos, ln)
            self.insert_bytes(self.crypto[lv], off, data, True)
            canon.append(venc(0x06) + venc(off) + venc(ln) + data)
            return False
        if t == 0x07:
            raise Fail('PROTOCOL_VIOLATION')
        if 0x08 <= t <= 0x0f:
            need_a()
            offFlag = bool(t & 4); lenFlag = bool(t & 2); finFlag = bool(t & 1)
            idv = vdec(pl, pos)
            off = vdec(pl, pos) if offFlag else 0
            if lenFlag:
                ln = vdec(pl, pos); data = take(pl, pos, ln)
            else:
                data = bytes(pl[pos[0]:]); pos[0] = len(pl)
            end = off + len(data)
            if end > MAXP: raise Fail(FE)
            s = self.ref_stream(idv, False)
            if s['fin'] is not None:
                if end > s['fin']: raise Fail('FINAL_SIZE_ERROR')
                if finFlag and end != s['fin']: raise Fail('FINAL_SIZE_ERROR')
            elif finFlag:
                if end < s['high']: raise Fail('FINAL_SIZE_ERROR')
                s['fin'] = end
            cand = max(s['high'], end)
            if cand > self.limStream: raise Fail('FLOW_CONTROL_ERROR')
            if self.used - s['high'] + cand > self.limConn: raise Fail('FLOW_CONTROL_ERROR')
            if data and s['reset'] is None:
                self.insert_bytes(s['data'], off, data, True)
            self.used += cand - s['high']
            s['high'] = cand
            out = venc(t) + venc(idv)
            if offFlag: out += venc(off)
            if lenFlag: out += venc(len(data))
            out += data
            canon.append(out)
            return False
        if t == 0x10:
            need_a()
            v = vdec(pl, pos)
            self.sendMaxData = max(self.sendMaxData, v)
            canon.append(venc(0x10) + venc(v))
            return False
        if t == 0x11:
            need_a()
            idv = vdec(pl, pos); v = vdec(pl, pos)
            s = self.ref_stream(idv, True)
            s['send_max'] = max(s['send_max'], v)
            canon.append(venc(0x11) + venc(idv) + venc(v))
            return False
        if t in (0x12, 0x13):
            need_a()
            v = vdec(pl, pos)
            if v > MAXST: raise Fail(FE)
            if t == 0x12: self.smsBidi = max(self.smsBidi, v)
            else: self.smsUni = max(self.smsUni, v)
            canon.append(venc(t) + venc(v))
            return False
        if t == 0x14:
            need_a()
            v = vdec(pl, pos)
            canon.append(venc(0x14) + venc(v))
            return False
        if t == 0x15:
            need_a()
            idv = vdec(pl, pos); v = vdec(pl, pos)
            self.ref_stream(idv, False)
            canon.append(venc(0x15) + venc(idv) + venc(v))
            return False
        if t in (0x16, 0x17):
            need_a()
            v = vdec(pl, pos)
            if v > MAXST: raise Fail(FE)
            canon.append(venc(t) + venc(v))
            return False
        if t == 0x18:
            need_a()
            seq = vdec(pl, pos); rpt = vdec(pl, pos)
            cidLen = take(pl, pos, 1)[0]
            if not (1 <= cidLen <= 20): raise Fail(FE)
            if rpt > seq: raise Fail(FE)
            cid = take(pl, pos, cidLen); token = take(pl, pos, 16)
            if seq in self.peerObs:
                pc, pt = self.peerObs[seq]
                if pc != cid or pt != token: raise Fail('PROTOCOL_VIOLATION')
            owner = self.peerOwner.get(cid)
            if owner is not None and owner != seq: raise Fail('PROTOCOL_VIOLATION')
            if seq not in self.peerObs:
                self.peerObs[seq] = (cid, token)
                self.peerOwner[cid] = seq
            self.threshold = max(self.threshold, rpt)
            self.peerActive = {s for s in self.peerActive if s >= self.threshold}
            if seq >= self.threshold:
                self.peerActive.add(seq)
            if len(self.peerActive) > self.limCids: raise Fail('CONNECTION_ID_LIMIT_ERROR')
            canon.append(venc(0x18) + venc(seq) + venc(rpt) + bytes([cidLen]) + cid + token)
            return False
        if t == 0x19:
            need_a()
            seq = vdec(pl, pos)
            if seq >= len(self.localCids) or seq == destSeq: raise Fail('PROTOCOL_VIOLATION')
            self.retiredLocal.add(seq)
            canon.append(venc(0x19) + venc(seq))
            return False
        if t in (0x1a, 0x1b):
            need_a()
            d = take(pl, pos, 8)
            canon.append(venc(t) + d)
            return False
        if t == 0x1c:
            err = vdec(pl, pos); trg = vdec(pl, pos); rl = vdec(pl, pos)
            r = take(pl, pos, rl)
            canon.append(venc(0x1c) + venc(err) + venc(trg) + venc(rl) + r)
            return True
        if t == 0x1d:
            need_a()
            err = vdec(pl, pos); rl = vdec(pl, pos)
            r = take(pl, pos, rl)
            canon.append(venc(0x1d) + venc(err) + venc(rl) + r)
            return True
        if t == 0x1e:
            raise Fail('PROTOCOL_VIOLATION')
        if t == 0x30:
            need_a()
            d = bytes(pl[pos[0]:]); pos[0] = len(pl)
            canon.append(venc(0x30) + d)
            return False
        if t == 0x31:
            need_a()
            ln = vdec(pl, pos); d = take(pl, pos, ln)
            canon.append(venc(0x31) + venc(ln) + d)
            return False
        raise Fail(FE)

    # ---------- output ----------
    def result(self):
        streams = []
        for idv in sorted(self.streams):
            s = self.streams[idv]
            rr, uniq, pref, h = ranges_of(s['data'])
            streams.append(dict(id=idv, high=s['high'], final=s['fin'], reset=s['reset'],
                                stop=s['stop'], send_max=s['send_max'],
                                ranges=[list(x) for x in rr], unique=uniq, prefix=pref, sha256=h))
        crypto = []
        for lv in ('I','H','A'):
            rr, uniq, pref, h = ranges_of(self.crypto[lv])
            crypto.append(dict(level=lv, ranges=[list(x) for x in rr], unique=uniq,
                               prefix=pref, sha256=h))
        acked = []
        for lv in ('I','H','A'):
            ivs = iv_merge(self.ack[lv])
            count = sum(e-s for s,e in ivs)
            hb = b''
            prefix = 0
            if ivs and ivs[0][0] == 0: prefix = ivs[0][1]
            for s, e in ivs:
                hb += s.to_bytes(8,'big') + e.to_bytes(8,'big')
            acked.append(dict(level=lv, count=count, intervals=len(ivs), prefix=prefix,
                              sha256=sha(hb), ecn=list(self.ecn[lv])))
        peer = [dict(sequence=s, id=self.peerObs[s][0].hex(), token=self.peerObs[s][1].hex())
                for s in sorted(self.peerActive)]
        retired = []
        rl = sorted(self.retiredLocal)
        i = 0
        while i < len(rl):
            j = i
            while j+1 < len(rl) and rl[j+1] == rl[j]+1: j += 1
            retired.append([rl[i], rl[j]+1])
            i = j+1
        epochs = [dict(epoch=g, min=v[0], max=v[1], count=v[2]) for g, v in sorted(self.epochs.items())]
        return dict(
            packets=self.outPackets,
            datagrams=self.outDatagrams,
            closed=self.closeInfo,
            keys=[k for k in ('I','H','A') if k in self.keys],
            received=dict(I=self.largest['I'], H=self.largest['H'], A=self.largest['A']),
            key_epoch=self.currentEpoch,
            epochs=epochs,
            opened=dict(bidi=self.openBidi, uni=self.openUni),
            used=self.used,
            send_max_data=self.sendMaxData,
            send_max_streams=dict(bidi=self.smsBidi, uni=self.smsUni),
            streams=streams,
            crypto=crypto,
            acknowledged=acked,
            peer_cids=peer,
            retire_prior_to=self.threshold,
            retired_local=retired)

def audit(t):
    r = Ref(t)
    r.run(t['events'])
    return r.result()
